from time import sleep, time

from requests import ReadTimeout

from taf.vran.vdu.enb.rest.exceptions import (
    APIRequestError,
    RequestTimeoutError
)

DEFAULT_ERROR_BACKOFF = 10

def poll_status(instance, endpoint, timeout, interval=5):
    """
    Polls the status of an operation until it's completed or timeout is reached.

    :param instance: instance of the class that has send_request method
    :param endpoint: API endpoint to poll
    :param timeout: timeout in seconds
    :param interval: polling interval in seconds, defaults to 5s

    :raises TimeoutError: If the operation does not complete within the timeout
    :raises RuntimeError: If the operation fails

    :returns: response if the operation is successful
    """
    stop_time = time() + timeout

    while time() < stop_time:
        try:
            response = instance.send_request(method="GET", endpoint=endpoint)

            if response["status"] in ["success", "succeeded"]:
                return response

            elif response["status"] in ["failed", "failure"]:
                raise RuntimeError(f"Operation failed. Operation info: {response}")

            sleep(interval)

        except (APIRequestError, RequestTimeoutError, ReadTimeout):
            sleep(DEFAULT_ERROR_BACKOFF if DEFAULT_ERROR_BACKOFF < timeout else interval)

    raise TimeoutError(f"Operation did not complete within {timeout} seconds")


def wait_for_reset_vdu_completion(instance, timeout, operation_id, polling_interval=5):
    """
    Polls the status of reset_vdu operation until it's completed or timeout is reached.
    Reset is considered to be completed when response with status code 404 is received
    meaning that operation with that ID no longer exists.

    :param instance: instance of the class that has send_request method
    :param timeout: timeout in seconds
    :param operation_id: ID of reset_vdu operation
    :param polling_interval: polling interval in seconds, defaults to 5s

    :raises TimeoutError: If the operation does not complete within the timeout
    :raises RuntimeError: If the operation fails

    :returns: response if the operation is successful
    """
    stop_time = time() + timeout

    while time() < stop_time:
        try:
            response = instance.send_request(
                method="GET", endpoint=f"/vdu/operations/resets/{operation_id}"
            )
            if response["status"] == "success":
                return response

            elif response["status"] == "failure":
                raise RuntimeError(f"Operation failed. Operation info: {response}")

            sleep(polling_interval)

        except (RequestTimeoutError, ReadTimeout, APIRequestError) as e:
            if isinstance(e, APIRequestError) and e.status_code == 404:
                return {"id": operation_id, "status": "completed"}

            sleep(DEFAULT_ERROR_BACKOFF if DEFAULT_ERROR_BACKOFF < timeout else polling_interval)

    raise TimeoutError(f"Reset vDU Operation did not complete within {timeout} seconds")
